  const [toolShelfIntroPulse, setToolShelfIntroPulse] = useState(false);
  const toolShelfIntroPlayedRef = useRef(false);
  const isToolShelfVisibleRef = useRef(isToolShelfVisible);
  useEffect(() => {
    isToolShelfVisibleRef.current = isToolShelfVisible;
  }, [isToolShelfVisible]);
  useEffect(() => {
    if (toolShelfIntroPlayedRef.current) return;
    if (isInitialScreen || showWelcome || activeVisualPanel !== 'canvas') return;
    toolShelfIntroPlayedRef.current = true;

    try {
      if (localStorage.getItem('landsurv.tool-shelf-intro.v2') === '1') return;
      localStorage.setItem('landsurv.tool-shelf-intro.v2', '1');
    } catch { /* private mode — still run once this session */ }

    // If an agent already opened a real panel, don't hide the user's workspace.
    if (isToolShelfVisibleRef.current) return;

    const closeDelayMs = 2200;
    const pulseDelayMs = 760;
    setIsToolShelfVisible(true);
    window.setTimeout(() => {
      setIsToolShelfVisible(false);
      window.setTimeout(() => setToolShelfIntroPulse(true), pulseDelayMs);
    }, closeDelayMs);
    window.setTimeout(
      () => setToolShelfIntroPulse(false),
      closeDelayMs + pulseDelayMs + 3600
    );
  }, [isInitialScreen, showWelcome, activeVisualPanel, setIsToolShelfVisible]);
  
  // Ref to always access current pointLists (avoids stale closure in async handlers)
  const pointListsRef = useRef(pointLists);
  useEffect(() => {
    pointListsRef.current = pointLists;
  }, [pointLists]);

  const centerlinesRef = useRef(centerlines);
  useEffect(() => {
    centerlinesRef.current = centerlines;
  }, [centerlines]);

  // Live-draw follow: while the agent streams points/lines onto the canvas, keep
  // the viewport framed on the geometry that has landed so far. Without this,
  // live drawing can happen entirely off-screen. The camera only moves during
  // the preview; a settled drawing never yanks the user's view.
  const livePreviewFitRef = useRef('');
  useEffect(() => {
    if (streamPreviewPoints.length === 0 && streamPreviewLines.length === 0) {
      livePreviewFitRef.current = '';
      return;
    }
    const canvas = canvas2dRef.current;
    if (!canvas) return;

    let minE = Infinity;
    let maxE = -Infinity;
    let minN = Infinity;
    let maxN = -Infinity;
    const include = (easting: number, northing: number) => {
      if (!Number.isFinite(easting) || !Number.isFinite(northing)) return;
      minE = Math.min(minE, easting);
      maxE = Math.max(maxE, easting);
      minN = Math.min(minN, northing);
      maxN = Math.max(maxN, northing);
    };

    const previewIndex = new Map<string, SurveyPoint>();
    for (const point of streamPreviewPoints) {
      previewIndex.set(point.pointNumber, point);
      include(point.easting, point.northing);
    }
    const lookup = (pointNumber: string) =>
      previewIndex.get(pointNumber) ?? pointMap.get(pointNumber);

    for (const line of streamPreviewLines) {
      const from = lookup(line.from)
        ?? (line.fromPt ? { easting: line.fromPt.x, northing: line.fromPt.y } : null);
      const to = lookup(line.to)
        ?? (line.toPt ? { easting: line.toPt.x, northing: line.toPt.y } : null);
      if (from) include(from.easting, from.northing);
      if (to) include(to.easting, to.northing);

      // A full circle's diameter extends past its center point.
      if (line.isCircle && line.curveRadius && line.curveRadius > 0) {
        if (line.circleCenter) {
          include(line.circleCenter.x - line.curveRadius, line.circleCenter.y - line.curveRadius);
          include(line.circleCenter.x + line.curveRadius, line.circleCenter.y + line.curveRadius);
        } else if (from) {
          include(from.easting - line.curveRadius, from.northing - line.curveRadius);
          include(from.easting + line.curveRadius, from.northing + line.curveRadius);
        }
      }
    }

    if (!Number.isFinite(minE) || !Number.isFinite(minN)) return;
    const signature = `${minE.toFixed(4)}|${maxE.toFixed(4)}|${minN.toFixed(4)}|${maxN.toFixed(4)}`;
    if (signature === livePreviewFitRef.current) return;
    livePreviewFitRef.current = signature;
    canvas.zoomToBbox(minE, maxE, minN, maxN, 0.3);
  }, [streamPreviewPoints, streamPreviewLines, pointMap, activeVisualPanel]);

  // Faint futuristic background grid on the drawing canvas � purely cosmetic,
  // toggled from the header next to the notification bell.
  const [isGridVisible, setIsGridVisible] = useState(true);

  // Agent draw mode: controls what the AI agents plot in response to requests
  const [agentDrawMode, setAgentDrawMode] = useState<'both' | 'points' | 'lines'>('both');
  const agentDrawModeRef = useRef<'both' | 'points' | 'lines'>('both');
  useEffect(() => {
    agentDrawModeRef.current = agentDrawMode;
  }, [agentDrawMode]);
  const cycleAgentDrawMode = useCallback(() => {
    setAgentDrawMode(prev => prev === 'both' ? 'points' : prev === 'points' ? 'lines' : 'both');
  }, []);

  // Next-draw annotation preference for the AI and CAD exporters. It never
  // hides existing labels; changing it only affects geometry drawn afterward.
  const [agentAnnotMode, setAgentAnnotMode] = useState<'both' | 'bearing' | 'distance'>('both');
  const cycleAgentAnnotMode = useCallback(() => {
    setAgentAnnotMode(prev => prev === 'both' ? 'bearing' : prev === 'bearing' ? 'distance' : 'both');
  }, []);

  useEffect(() => {
    setBearingDistanceMode(agentAnnotMode);
  }, [agentAnnotMode]);

  // -- Built-in survey symbol visibility (opt-in, request-scoped) -----------
  // Built-in library symbols (tree, manhole, hydrant, �) default to OFF. They
  // only render for the specific symbol ids the user explicitly asked for via
  // chat ("draw tree symbols") or the Symbol Manager eye toggle. This replaces
  // the earlier always-on fallback. Persisted so a session's choices survive a
  // reload. The special sentinel '*' means "all built-in symbols enabled".
  const ENABLED_BUILTIN_STORAGE_KEY = 'landsurv.enabledBuiltinSymbolIds.v1';
  const [enabledBuiltinSymbolIds, setEnabledBuiltinSymbolIds] = useState<Set<string>>(() => {
    try {
      const raw = localStorage.getItem(ENABLED_BUILTIN_STORAGE_KEY);
      if (!raw) return new Set();
      const arr = JSON.parse(raw);
      return Array.isArray(arr) ? new Set(arr.filter((s): s is string => typeof s === 'string')) : new Set();
    } catch {
      return new Set();
    }
  });
  useEffect(() => {
    try {
      localStorage.setItem(ENABLED_BUILTIN_STORAGE_KEY, JSON.stringify([...enabledBuiltinSymbolIds]));
    } catch { /* quota / privacy mode � ignore */ }
  }, [enabledBuiltinSymbolIds]);

  // One-time migration: the earlier always-on fix persisted synthesized
  // `builtin:`-prefixed entries directly into customSymbols. Those would keep
  // rendering (via the priority-1 custom-symbol path) even after we flip the
  // default to off, silently defeating the gate. Strip them once on mount.
  const didStripStaleBuiltinsRef = useRef(false);
  useEffect(() => {
    if (didStripStaleBuiltinsRef.current) return;
    didStripStaleBuiltinsRef.current = true;
    setCustomSymbols(prev => {
      const cleaned = prev.filter(s => !s.id.startsWith('builtin:'));
      return cleaned.length === prev.length ? prev : cleaned;
    });
  }, [setCustomSymbols]);

  // Apply a parsed symbol-visibility command to the enabled-ids set. Uses the
  // '*' sentinel to mean "all built-in symbols enabled". Disabling specific
  // ids while '*' is active expands '*' to the full id set minus the removed
  // ones so the toggle stays coherent.
  const ALL_BUILTIN_IDS = useMemo(() => SURVEY_SYMBOL_LIBRARY.map(s => s.id), []);
  const applySymbolVisibilityCommand = useCallback((cmd: SymbolVisibilityCommand) => {
    setEnabledBuiltinSymbolIds(prev => {
      const next = new Set(prev);
      if (cmd.ids === 'all') {
        if (cmd.action === 'enable') return new Set(['*']);
        return new Set(); // disable all
      }
      if (cmd.action === 'enable') {
        cmd.ids.forEach(id => next.add(id));
        return next;
      }
      // disable specific ids
      if (next.has('*')) {
        // Expand the "all" sentinel to concrete ids, then remove requested.
        const expanded = new Set(ALL_BUILTIN_IDS);
        cmd.ids.forEach(id => expanded.delete(id));
        return expanded;
      }
      cmd.ids.forEach(id => next.delete(id));
      return next;
    });
  }, [ALL_BUILTIN_IDS, setEnabledBuiltinSymbolIds]);

  
  // TIN shading lives here so the top bar can toggle it after the control
